// === Tab: Scale ===
class Scale {
	constructor(pos, ang, mat) {
		this.pos = pos;
		this.ang = ang;
		this.mat = mat;
	}

	show() {
		shininess(5);
		fill(this.mat);
		noStroke();
		push();
		rotateY(twist.y * this.pos.x / 1000);
		rotateZ(twist.z * this.pos.x / 2000);
		if (this.pos.x > 0) rotateY(wiggle * this.pos.x / 2000);
		translate(this.pos);
		rotateY(this.ang.y);
		rotateX(-this.ang.x);
		ellipse(0, 0, 15, 15);
		pop();
		push();
		rotateY(twist.y * this.pos.x / 1000);
		rotateZ(twist.z * this.pos.x / 2000);
		if (this.pos.x > 0) rotateY(wiggle * this.pos.x / 2000);
		translate(this.pos.x, this.pos.y, -this.pos.z);
		rotateY(-this.ang.y);
		rotateX(this.ang.x);
		ellipse(0, 0, 15, 15);
		pop();
	}
}

// === Tab: Bubble ===
class Bubble {
	constructor(pos, rad) {
		this.pos = pos;
		this.yvel = -0.1;
		this.rad = rad;
		this.alive = true;
	}
	show() {
		push();
		translate(this.pos);
		fill('rgba(255,255,255,0.3)');
		ellipsoid(this.rad, this.rad - this.yvel / 2, this.rad);
		pop();
	}
	move() {
		this.pos.y -= this.yvel;
		this.yvel += 0.2;
		this.rad += 0.1;
		if (this.pos.y < -height / 6) this.alive = false;
	}
}

