// For the #WCCChallenge, theme: "aqua".

let tetra;
let scales = [];
let bubbles = [];
let orient, otarget;
let twist, ttwist;
let tpos, tvel;
let amp = 0;
let wiggle = 0;

function preload() {
	tetra = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/tetra2.png');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	const detail = 1200;
	tetra.resize(detail, 0);
	makeScales();
	orient = createVector(0, 0, 0);
	otarget = createVector(0, 0, 0);
	tpos = createVector(0, 0, 0);
	tvel = createVector(0, 0, 0);
	twist = createVector(0, 0, 0);
	ttwist = createVector(0, 0, 0);
}

function draw() {
	orbitControl();
	rotateX(-PI / 8);
	background(0);
	ambientLight(200);
	pointLight(150, 150, 150, height/2, -height/2, 2 * height);
	moveFish();
	drawBubbles();
	drawFish();
	drawBowl();
	checkInputs();
	makeBubbles();
}


function moveFish() {
	if (frameCount > 20) {
		orient.lerp(otarget, 0.1);
		tvel.z += amp * sin(orient.y);
		tvel.x -= amp * cos(orient.y);
		tpos.add(tvel);
		if (tpos.mag() > 2 * height) {
			tpos.sub(tvel);
			tvel.mult(-0.25);
		}
		tvel.mult(0.95);
		ttwist.mult(0.8);
		otarget.z *= 0.95;
		amp *= 0.8;
		twist.lerp(ttwist, 0.25);
		wiggle = (PI / 8) * amp * sin(frameCount / 2);
	}
}

function drawFish() {
	push();
	scale(0.15 * height / 566);
	translate(tpos);
	rotateY(orient.y);
	rotateZ(orient.z);
	for (let s of scales) {
		s.show();
	}
	pop();
}

function drawBowl() {
	specularMaterial(100);
	shininess(5);
	metalness(10);
	push();
	translate(0, -5, 0)
	fill('rgba(0,255,255,0.1)'); // aqua agua!
	cylinder(height / 1.5 - 5, height / 3 - 10, 32, 1, true, true);
	pop();
	push();
	fill('rgba(255,255,255,0.05)');
	translate(0, -50, 0);
	cylinder(height / 1.49, height / 3 + 100, 32, 1, false, true);
	translate(0, -height / 6 - 50, 0);
	rotateX(HALF_PI);
	torus(height / 1.49, height / 100, 64, 16);
	pop();
}

function makeBubbles(){
	if (floor(random(40)) == 0) {
		let sc = 0.25 * height / 566;
		bubbles.push(new Bubble(createVector(tpos.x*sc - (height/6)*cos(orient.y), tpos.y*sc, tpos.z*sc + (height/6)*sin(orient.y)), 2*height/548));
	}
}

function drawBubbles() {
	bubbles = bubbles.filter(b => b.alive);
	for (let b of bubbles) {
		b.move();
		b.show();
	}
}

function makeScales() {
	for (let y = 0; y < tetra.height; y += 15) {
		for (let x = 0; x < tetra.width; x += 15) {
			let c = color(tetra.get(x, y));
			if (brightness(window.color(c)) > 20) {
				fill(c);
				noStroke();
				let ax = map((y - tetra.height / 2), -tetra.height / 8, tetra.height / 3, -HALF_PI, HALF_PI, true);
				let ay = map((x - tetra.width / 2), -tetra.width / 2, tetra.width / 3, -HALF_PI, HALF_PI, true);
				let tz = cos(ax) * (tetra.height / 6) * cos(ay);
				let z = max(-1, tz);
				if (y < tetra.height / 4 || y > 4 * tetra.height / 5) ax = 0;
				if (x > 5 * tetra.width / 6) ay = 0;
				let ang = createVector(ax, ay, 0);
				let pos = createVector(x - tetra.width / 2, y - tetra.height / 2, z);
				scales.push(new Scale(pos, ang, c));
			}
		}
	}
}

